                Invoic.ReffNo = Invoic.InvGlobalID;
                Invoic.RefDate = Invoic.InvDate;
                Invoic.InvDate = txtDate_Value;
                Invoic.ISNew = true;

                ItemOper.CalcRows(ref Invoic);
                BindingDGV(true);
                BindingControls();
            }
            catch { }
        }

