private T GetSelectedValue<T>(ComboBox cmb)
        {
            try
            {
                if (cmb.SelectedItem is DataRowView row &&
                    cmb.SelectedValuePath != null)
                {
                    var val = row[cmb.SelectedValuePath];
                    if (val != DBNull.Value)
                        return (T)Convert.ChangeType(val, typeof(T));
                }
            }
            catch { }
            return default(T);
        }

