private void LoadCustomers()
        {
            try
            {
                int customerType = 2;
                if (InvType != 4 && InvType == 5)
                {
                    customerType = 1;
                }

                using (SqlDataAdapter adapter = new SqlDataAdapter(
                    "select id,name from Customers where (type=" + customerType + " or type=3) order by id",
