                    var calc = new Frm_Calculator { };
                    calc.TextBox1.Text = "1";
                    calc.ShowDialog();
                    row.QuantDgv = Properties.Settings.Default.QTY.ToString();
                }

                CalcRowValues(index);
                CalcTot();
            }
